#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

const ll MOD = 1000000007LL;

ll prefixAccum(ll n, ll b) {
    if (n <= 0) return 0;
    ll x = n % MOD;
    ll y = (n + 1) % MOD;
    ll triangular = (ll)((i128)x * y % MOD * ((MOD + 1) / 2) % MOD);
    return (ll)((i128)(b % MOD) * triangular % MOD);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    cin >> a >> b;

    ll sum = 0;
    ll temp = (ll)((i128)b * (b - 1) / 2);
    ll extra = -1, obba7 = 0, zawwed = 0, prev = 0;

    for (ll i = 1; i < b; ++i)
        zawwed = (zawwed + (ll)((i128)(i % MOD) * (i % MOD) % MOD)) % MOD;

    for (ll i = 1; i <= a; ++i) {
        if (extra != -1) {
            sum = (sum + prev + obba7) % MOD;
            prev = sum;
            continue;
        }

        if (i == 1) {
            for (ll j = 1; j < b; ++j) {
                ll l = j - 1;
                ll r = 2 * j - 1;
                sum = (sum + prefixAccum(r, b) - prefixAccum(l, b)) % MOD;
            }
            sum = (sum + zawwed) % MOD;
        } else {
            extra = 0;
            ll hoba = temp;

            for (ll j = 1; j < b; ++j) {
                ll l = 2 * j - 1;
                ll r = l + min(j, hoba);

                if (j == 1) {
                    l = 1;
                    r = 2;
                }

                extra = (extra + prefixAccum(r, b) - prefixAccum(l, b)) % MOD;
                hoba -= j;
            }

            extra = (extra + zawwed) % MOD;
            obba7 = (extra - sum + MOD) % MOD;
            sum = (sum + extra) % MOD;
            prev = extra;
        }
    }

    cout << (sum + MOD) % MOD;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

ll normalize(ll value) {
    value %= MOD;
    if (value < 0) value += MOD;
    return value;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    cin >> a >> b;

    auto accum = [b](ll index) -> ll {
        ll x = index % MOD;
        ll y = (index + 1) % MOD;

        if ((index & 1LL) == 0)
            x = x * ((MOD + 1) / 2) % MOD;
        else
            y = y * ((MOD + 1) / 2) % MOD;

        return static_cast<ll>(
            static_cast<__int128>(b % MOD) * x % MOD * y % MOD
        );
    };

    ll sum = 0;
    ll temp = b * (b - 1) / 2;
    ll extra = -1;
    ll obba7 = 0;
    ll zawwed = 0;
    ll prev = 0;

    for (ll i = 1; i < b; ++i)
        zawwed = (zawwed + static_cast<ll>(
            static_cast<__int128>(i % MOD) * (i % MOD) % MOD
        )) % MOD;

    for (ll i = 1; i <= a; ++i) {
        if (extra != -1) {
            sum = (sum + prev + obba7) % MOD;
            prev = sum;
            continue;
        }

        if (i == 1) {
            for (ll j = 1; j < b; ++j) {
                ll l = j - 1;
                ll r = 2 * j - 1;
                sum = (sum + accum(r) - accum(l)) % MOD;
            }
            sum = (sum + zawwed) % MOD;
        } else {
            extra = 0;
            ll hoba = temp;

            for (ll j = 1; j < b; ++j) {
                ll l = 2 * j - 1;
                ll r = min(l + j, l + hoba);

                if (j == 1) {
                    r = j + 1;
                    l = 1;
                }

                extra = (extra + accum(r) - accum(l)) % MOD;
                hoba -= j;
            }

            extra = (extra + zawwed) % MOD;
            obba7 = normalize(extra - sum);
            sum = (sum + extra) % MOD;
            prev = extra;
        }
    }

    cout << sum;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;

constexpr ll MOD = 1'000'000'007LL;

ll normalize(ll value)
{
    value %= MOD;
    if (value < 0)
        value += MOD;
    return value;
}

ll prefixSum(ll n, ll b)
{
    if (n <= 0)
        return 0;

    i128 x = n;
    i128 y = static_cast<i128>(n) + 1;

    if (n % 2 == 0)
        x /= 2;
    else
        y /= 2;

    const ll triangular = static_cast<ll>((x % MOD) * (y % MOD) % MOD);
    return static_cast<ll>(
        static_cast<i128>(normalize(b)) * triangular % MOD
    );
}

int main()
