    ll prev = 0;
    ll zawwed = 0;

    for (ll i = 1; i < b; ++i)
        zawwed = (zawwed + static_cast<ll>(
            static_cast<i128>(i % MOD) * (i % MOD) % MOD
        )) % MOD;

    const i128 temp = static_cast<i128>(b) * (b - 1) / 2;

    for (ll i = 1; i <= a; ++i)
    {
        if (extra != -1)
        {
            sum = normalize(sum + prev + obba7);
            prev = sum;
            continue;
        }

        if (i == 1)
        {
            for (ll j = 1; j < b; ++j)
            {
                const ll l = j - 1;
                const ll r = 2 * j - 1;
                sum = normalize(sum + prefixSum(r, b) - prefixSum(l, b));
            }
            sum = normalize(sum + zawwed);
        }
        else
        {
            extra = 0;
            i128 hoba = temp;

            for (ll j = 1; j < b; ++j)
            {
                ll l = 2 * j - 1;
                ll r = l + static_cast<ll>(min<i128>(j, hoba));

                if (j == 1)
                {
                    l = 1;
                    r = 2;
                }

                extra = normalize(
                    extra + prefixSum(r, b) - prefixSum(l, b)
                );
                hoba -= j;
            }

            extra = normalize(extra + zawwed);
            obba7 = normalize(extra - sum);
            sum = normalize(sum + extra);
            prev = extra;
        }
    }

    cout << sum;
    return 0;
}

